internal static class CommentJson
{
    // Defensive client-side ceilings for the current comment API boundary.
    // They keep malformed or compromised responses from producing unbounded
    // agent context/stdout while allowing normal comment payload sizes. These
    // are not a server contract; update the constants and tests together if
    // the API publishes larger supported limits.
    private const int MaxComments = 1000;
    private const int MaxAuthorLength = 256;
    private const int MaxTimestampLength = 128;
    private const int MaxContentLength = 8192;

    private static readonly string[] CreatedCommentIdPropertyNames = ["id", "commentId"];
    private static readonly string[] CommentArrayPropertyNames = ["comments", "items", "data"];
    private static readonly string[] TimestampPropertyNames = ["timestamp", "createdAt", "createdOn", "created", "updatedAt"];
    private static readonly string[] ContentPropertyNames = ["content", "body", "text"];
    private static readonly string[] NestedAuthorPropertyNames = ["displayName", "name", "email", "id"];
    private static readonly string[] FallbackAuthorPropertyNames = ["authorName", "createdBy", "createdByName", "userName", "userId"];

    // The service has returned these aliases across scaffold iterations. Keep
    // accepted names centralized so the API boundary remains easy to audit.
    public static string ExtractCreatedCommentId(string raw)
    {
        if (string.IsNullOrWhiteSpace(raw))
        {
            throw new InvalidOperationException("API response did not include a comment id.");
        }

        using var document = ParseDocument(raw);
        var root = document.RootElement;
        if (root.ValueKind == JsonValueKind.String)
        {
            var value = root.GetString();
            if (!string.IsNullOrWhiteSpace(value))
            {
                return value;
            }
        }

        if (FirstScalar(root, CreatedCommentIdPropertyNames) is { } id ||
            TryGetNestedScalar(root, "comment", "id", out id))
        {
            if (!string.IsNullOrWhiteSpace(id))
            {
                return id;
            }
        }

        throw new InvalidOperationException("API response did not include a comment id.");
    }

    public static IReadOnlyList<TaskComment> ReadComments(string raw)
    {
        if (string.IsNullOrWhiteSpace(raw))
        {
            throw new InvalidOperationException("API response was not a comment array or wrapper object.");
        }

        using var document = ParseDocument(raw);
        var root = document.RootElement;
        var comments = new List<TaskComment>();
        foreach (var comment in EnumerateCommentElements(root))
        {
            if (comments.Count >= MaxComments)
            {
                throw new InvalidOperationException($"API returned more than {MaxComments} comments.");
            }

            comments.Add(ReadComment(comment, comments.Count));
        }

        return comments;
    }

    private static TaskComment ReadComment(JsonElement comment, int index)
    {
        if (comment.ValueKind != JsonValueKind.Object)
        {
            throw new InvalidOperationException($"API comment at index {index} was not an object.");
        }

        return new TaskComment(
            RequiredAuthor(comment, index),
            RequiredScalar(comment, index, "timestamp", MaxTimestampLength, TimestampPropertyNames),
            RequiredScalar(comment, index, "content", MaxContentLength, ContentPropertyNames));
    }

    private static JsonDocument ParseDocument(string raw)
    {
        try
        {
            return JsonDocument.Parse(raw);
        }
        catch (JsonException exception)
        {
            throw new InvalidOperationException("API response was malformed JSON.", exception);
        }
    }

    private static IEnumerable<JsonElement> EnumerateCommentElements(JsonElement root)
    {
        if (root.ValueKind == JsonValueKind.Array)
        {
            foreach (var comment in root.EnumerateArray())
            {
                yield return comment;
            }

            yield break;
        }

        if (root.ValueKind == JsonValueKind.Object)
        {
            foreach (var propertyName in CommentArrayPropertyNames)
            {
                if (TryGetProperty(root, propertyName, out var property))
                {
                    if (property.ValueKind == JsonValueKind.Array)
                    {
                        foreach (var comment in property.EnumerateArray())
                        {
                            yield return comment;
                        }

                        yield break;
                    }

                    throw new InvalidOperationException(
                        $"API response property '{propertyName}' was not a comment array.");
                }
            }

            throw new InvalidOperationException(
                "API response did not include a comments, items, or data comment array.");
        }

        throw new InvalidOperationException("API response was not a comment array or wrapper object.");
    }

    private static string RequiredAuthor(JsonElement comment, int index)
    {
        if (TryGetProperty(comment, "author", out var author))
        {
            if (TryConvertScalar(author, out var authorValue))
            {
                return BoundedScalar(authorValue, index, "author", MaxAuthorLength);
            }

            if (author.ValueKind == JsonValueKind.Object)
            {
                var nestedAuthor = FirstScalar(author, NestedAuthorPropertyNames);
                if (nestedAuthor is not null)
                {
                    return BoundedScalar(nestedAuthor, index, "author", MaxAuthorLength);
                }
            }
        }

        var fallbackAuthor = FirstScalar(comment, FallbackAuthorPropertyNames);
        if (fallbackAuthor is not null)
        {
            return BoundedScalar(fallbackAuthor, index, "author", MaxAuthorLength);
        }

        throw new InvalidOperationException($"API comment at index {index} did not include an author.");
    }

    private static string RequiredScalar(
        JsonElement root,
        int index,
        string fieldName,
        int maxLength,
        params string[] propertyNames)
    {
        var value = FirstScalar(root, propertyNames);
        if (value is not null)
        {
            return BoundedScalar(value, index, fieldName, maxLength);
        }

        throw new InvalidOperationException(
            $"API comment at index {index} did not include a {fieldName}.");
    }

    private static string BoundedScalar(string value, int index, string fieldName, int maxLength)
    {
        if (value.Length <= maxLength)
        {
            return value;
        }

        throw new InvalidOperationException(
            $"API comment at index {index} {fieldName} exceeded {maxLength} characters.");
    }

    private static bool TryGetNestedScalar(JsonElement root, string propertyName, string nestedPropertyName, out string value)
    {
        value = "";
        if (!TryGetProperty(root, propertyName, out var property) || property.ValueKind != JsonValueKind.Object)
        {
            return false;
        }

        return TryGetScalar(property, nestedPropertyName, out value);
    }

    private static string? FirstScalar(JsonElement root, params string[] propertyNames)
    {
        foreach (var propertyName in propertyNames)
        {
            if (TryGetScalar(root, propertyName, out var value))
            {
                return value;
            }
        }

        return null;
    }

    private static bool TryGetScalar(JsonElement root, string propertyName, out string value)
    {
        value = "";
        if (!TryGetProperty(root, propertyName, out var property))
        {
            return false;
        }

        return TryConvertScalar(property, out value);
    }

    private static bool TryGetProperty(JsonElement root, string propertyName, out JsonElement property)
    {
        property = default;
        if (root.ValueKind != JsonValueKind.Object)
        {
            return false;
        }

        foreach (var candidate in root.EnumerateObject())
        {
            if (StringComparer.OrdinalIgnoreCase.Equals(candidate.Name, propertyName))
            {
                property = candidate.Value;
                return true;
            }
        }

        return false;
    }

    private static bool TryConvertScalar(JsonElement value, out string scalar)
    {
        scalar = "";
        if (value.ValueKind == JsonValueKind.String)
        {
            scalar = value.GetString() ?? "";
            return true;
        }

        return false;
    }
}

