internal sealed class TypeRegistrar : ITypeRegistrar, ITypeResolver
{
    private readonly Dictionary<Type, Func<object?>> _registrations = [];

    public ITypeResolver Build()
    {
        return this;
    }

    public void Register(Type service, Type implementation)
    {
        _registrations[service] = () => CreateInstance(implementation);
    }

    public void RegisterInstance(Type service, object implementation)
    {
        _registrations[service] = () => implementation;
    }

    public void RegisterLazy(Type service, Func<object> factory)
    {
        object? instance = null;
        _registrations[service] = () => instance ??= factory();
    }

    public object? Resolve(Type? type)
    {
        if (type is null)
        {
            return null;
        }

        if (_registrations.TryGetValue(type, out var factory))
        {
            return factory();
        }

        if (type.IsAbstract || type.IsInterface)
        {
            if (type.IsGenericType && type.GetGenericTypeDefinition() == typeof(IEnumerable<>))
            {
                return Array.CreateInstance(type.GetGenericArguments()[0], 0);
            }

            return null;
        }

        return CreateInstance(type);
    }

    private object CreateInstance(Type type)
    {
        var constructors = type.GetConstructors(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
            .OrderByDescending(constructor => constructor.GetParameters().Length);

        foreach (var constructor in constructors)
        {
            var parameters = constructor.GetParameters();
            var arguments = new object?[parameters.Length];
            var canUse = true;

            for (var index = 0; index < parameters.Length; index++)
            {
                var argument = Resolve(parameters[index].ParameterType);
                if (argument is null)
                {
                    canUse = false;
                    break;
                }

                arguments[index] = argument;
            }

            if (canUse)
            {
                return constructor.Invoke(arguments);
            }
        }

        return Activator.CreateInstance(type, nonPublic: true)
            ?? throw new InvalidOperationException($"Could not create instance of {type.FullName}.");
    }
}

